CREATE TEMP TABLE egglog_scalar_outcome_1_0 AS
                     WITH selected AS (
                         SELECT __wave, __event_ordinal, c0, c1, c2
                         FROM (
                             SELECT queued.*,
                                    row_number() OVER (
                                        PARTITION BY c0 ORDER BY __event_ordinal
                                    ) AS __key_rank
                             FROM egglog_scalar_queue_1_0 AS queued
                             WHERE __wave = CAST('0' AS UBIGINT)
                         )
                         WHERE __key_rank = 1
                     )
                     SELECT selected.__wave,
                            selected.__event_ordinal,
                            selected.c0 AS new_c0, selected.c1 AS new_c1, selected.c2 AS new_c2,
                            existing.c0 AS old_c0, existing.c1 AS old_c1, existing.c2 AS old_c2,
                            existing.__generation AS old_generation,
                            existing.__subsumed AS old_subsumed
                     FROM selected
                     LEFT JOIN egglog_function_24 AS existing ON existing.c0 IS NOT DISTINCT FROM selected.c0;

