CREATE TEMP TABLE egglog_scalar_collision_1_0 AS
                     SELECT outcome.*,
                            CASE WHEN old_c1 < new_c1
                                 THEN old_c1 ELSE new_c1 END AS min_identity,
                            CASE WHEN old_c1 > new_c1
                                 THEN old_c1 ELSE new_c1 END AS max_identity,
                            CASE WHEN old_c1 < new_c1
                                 THEN old_c2 ELSE new_c2 END AS lo_payload,
                            CASE WHEN old_c1 > new_c1
                                 THEN old_c2 ELSE new_c2 END AS hi_payload,
                            row_number() OVER (ORDER BY __event_ordinal)
                                AS __collision_ordinal
                     FROM egglog_scalar_outcome_1_0 AS outcome
                     WHERE old_generation IS NOT NULL
